# Ticket data, part 1 (W1). Each ticket is a dict; see gen.py for rendering.
T = []
def t(**k):
    k.setdefault("ext", []); k.setdefault("gates", []); k.setdefault("signoff", "n")
    k.setdefault("reembed", "n"); k.setdefault("services", "none"); k.setdefault("gpu", "n")
    k.setdefault("serial_after", [])
    T.append(k)

